import{_ as n,C as o,o as i,c as r,a2 as t,E as l}from"./chunks/framework.CBxkvBm_.js";const f=JSON.parse('{"title":"Acausal Connector Balancing & Stream Mixing","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/connector-balancing.md","filePath":"algorithms/connector-balancing.md"}'),s={name:"algorithms/connector-balancing.md"};function c(d,e,m,h,u,g){const a=o("MermaidBlock");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="acausal-connector-balancing-stream-mixing" tabindex="-1">Acausal Connector Balancing &amp; Stream Mixing <a class="header-anchor" href="#acausal-connector-balancing-stream-mixing" aria-label="Permalink to &quot;Acausal Connector Balancing &amp; Stream Mixing&quot;">​</a></h1><p><strong>Implementation</strong>: <code>ConnectionSetResolver</code> &amp; <code>IntUnionFind</code> in <a href="https://github.com/modelscript/modelscript/tree/main/languages/modelica/src/connections.ts" target="_blank" rel="noreferrer"><code>languages/modelica/src/connections.ts</code></a></p><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><h3 id="acausal-physical-modeling-connection-sets" tabindex="-1">Acausal Physical Modeling &amp; Connection Sets <a class="header-anchor" href="#acausal-physical-modeling-connection-sets" aria-label="Permalink to &quot;Acausal Physical Modeling &amp; Connection Sets&quot;">​</a></h3><ul><li><strong>Mattsson, S. E., Elmqvist, H., &amp; Otter, M. (1998)</strong>. <em>&quot;Physical system modeling with Modelica.&quot;</em><br><strong>Control Engineering Practice</strong>, 6(4), pp. 501–510.<br> DOI: <a href="https://doi.org/10.1016/S0967-0661(98)00047-1" target="_blank" rel="noreferrer">10.1016/S0967-0661(98)00047-1</a></li><li><strong>Tarjan, R. E. (1975)</strong>. <em>&quot;Efficiency of a good but not linear set union algorithm.&quot;</em><br><strong>Journal of the ACM</strong>, 22(2), pp. 215–225.<br> DOI: <a href="https://doi.org/10.1145/321879.321884" target="_blank" rel="noreferrer">10.1145/321879.321884</a> <em>(Disjoint-Set Union-Find)</em></li></ul><h3 id="stream-connectors-convective-transport" tabindex="-1">Stream Connectors &amp; Convective Transport <a class="header-anchor" href="#stream-connectors-convective-transport" aria-label="Permalink to &quot;Stream Connectors &amp; Convective Transport&quot;">​</a></h3><ul><li><strong>Franke, R., Casella, F., Otter, M., Sielemann, M., Elmqvist, H., Mattsson, S. E., &amp; Olsson, H. (2009)</strong>. <em>&quot;Stream Connectors - An Extension of Modelica for Device-Oriented Modeling of Convective Transport.&quot;</em><br><strong>Proceedings of the 7th Modelica Conference</strong>, pp. 116–123.<br> DOI: <a href="https://doi.org/10.3384/ecp09430076" target="_blank" rel="noreferrer">10.3384/ecp09430076</a></li></ul><h3 id="expandable-connectors-multi-domain-bus-modeling" tabindex="-1">Expandable Connectors &amp; Multi-Domain Bus Modeling <a class="header-anchor" href="#expandable-connectors-multi-domain-bus-modeling" aria-label="Permalink to &quot;Expandable Connectors &amp; Multi-Domain Bus Modeling&quot;">​</a></h3><ul><li><strong>Otter, M., Elmqvist, H., &amp; Mattsson, S. E. (2005)</strong>. <em>&quot;Object-oriented modeling of bus systems with Modelica.&quot;</em><br><strong>Proceedings of the 4th Modelica Conference</strong>, pp. 295–308.<br><a href="https://modelica.org/events/Conference2005/online_proceedings/Session4/Session4a2.pdf" target="_blank" rel="noreferrer">Paper PDF</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>Unlike classical block diagrams (such as causal signal-flow block diagrams) where connections represent directional causal signal flows ($y = f(u)$), ModelScript models <strong>acausal physical interaction</strong> across multi-energy domains:</p><ul><li><strong>Electrical</strong>: Voltage $v$ (potential) and Current $i$ (flow).</li><li><strong>Hydraulic &amp; Pneumatic</strong>: Pressure $p$ (potential) and Volume/Mass flow rate $q$ (flow).</li><li><strong>Translational Mechanics</strong>: Position/Velocity $s, v$ (potential) and Force $f$ (flow).</li><li><strong>Rotational Mechanics</strong>: Angle/Angular velocity $\\phi, \\omega$ (potential) and Torque $\\tau$ (flow).</li><li><strong>Thermal &amp; Fluid Transport</strong>: Temperature/Enthalpy $h$ (stream) and Heat/Mass flow $\\dot{m}$ (flow).</li></ul><p>In acausal modeling, connection statements <code>connect(a, b)</code> do not dictate computational causality. The compiler must automatically generate:</p><ol><li><strong>Potential Equality Equations</strong>: Enforcing that all across-variables in a connection set share an identical value.</li><li><strong>Kirchhoff Flow Equations</strong>: Enforcing conservation of mass, charge, or energy such that all through-variables sum to zero at the junction.</li><li><strong>Convective Stream Transport Equations</strong>: Resolving thermodynamic mixing when fluid direction reverses ($m_j \\gtrless 0$) without introducing singular divisions near zero mass flow.</li></ol><hr><h2 id="balancing-algorithm-mathematical-formulation" tabindex="-1">Balancing Algorithm &amp; Mathematical Formulation <a class="header-anchor" href="#balancing-algorithm-mathematical-formulation" aria-label="Permalink to &quot;Balancing Algorithm &amp; Mathematical Formulation&quot;">​</a></h2>',18)),l(a,{code:"flowchart%20TD%0A%20%20%20%20CONNECTS%5B%22Modelica%20Connect%20Equations%3A%20connect(c_1%2C%20c_2)%22%5D%20--%3E%20DISJOINT%5B%22Tarjan%20Union-Find%20Clustering%3Cbr%2F%3EBuild%20Connected%20Sets%20S_k%22%5D%0A%20%20%20%20DISJOINT%20--%3E%20CLASSIFY%7B%22Examine%20Port%20Variables%20in%20S_k%22%7D%0A%20%20%20%20CLASSIFY%20--%3E%7CPotential%20%2F%20Non-flow%7C%20POT%5B%22Potential%20Equalization%3Cbr%2F%3Ev_1%20%3D%20v_2%20%3D%20...%20%3D%20v_m%3Cbr%2F%3E(m%20-%201%20equations)%22%5D%0A%20%20%20%20CLASSIFY%20--%3E%7CFlow%20%2F%20Through%7C%20FLOW%5B%22Kirchhoff%20Balance%3Cbr%2F%3E%E2%88%91%20f_j%20%3D%200%3Cbr%2F%3E(1%20conservation%20equation)%22%5D%0A%20%20%20%20CLASSIFY%20--%3E%7CStream%7C%20STREAM%5B%22Upstream%20Operator%20Formulation%3Cbr%2F%3EinStream(c_j.h)%20%26%20actualStream(c_j.h)%3Cbr%2F%3EZero-Flow%20Regularization%22%5D%0A%20%20%20%20POT%20--%3E%20DAE%5B%22DAEBuilder%20Linear%20Equations%22%5D%0A%20%20%20%20FLOW%20--%3E%20DAE%0A%20%20%20%20STREAM%20--%3E%20DAE%0A"}),e[1]||(e[1]=t('<h3 id="_1-disjoint-connection-set-resolution-union-find" tabindex="-1">1. Disjoint Connection Set Resolution (Union-Find) <a class="header-anchor" href="#_1-disjoint-connection-set-resolution-union-find" aria-label="Permalink to &quot;1. Disjoint Connection Set Resolution (Union-Find)&quot;">​</a></h3><p>The set of all declared <code>connect(c_a, c_b)</code> statements forms an undirected graph. ModelScript partitions all connector references into disjoint equivalence classes using an integer array-based Union-Find with path compression and rank heuristics: $$\\alpha(N) \\le 4 \\quad \\text{for all physical models}$$ For each connection set $S = {c_1, c_2, \\dots, c_m}$ of size $m$:</p><h3 id="_2-potential-variable-equalization" tabindex="-1">2. Potential Variable Equalization <a class="header-anchor" href="#_2-potential-variable-equalization" aria-label="Permalink to &quot;2. Potential Variable Equalization&quot;">​</a></h3><p>For every non-flow, non-stream variable $v$ declared inside the connector type: $$v(c_1) = v(c_2) = \\dots = v(c_m)$$ This yields exactly $m - 1$ scalar equations. One variable is chosen as the canonical representative, eliminating $m - 1$ redundant states during alias elimination.</p><h3 id="_3-kirchhoff-flow-variable-balancing" tabindex="-1">3. Kirchhoff Flow Variable Balancing <a class="header-anchor" href="#_3-kirchhoff-flow-variable-balancing" aria-label="Permalink to &quot;3. Kirchhoff Flow Variable Balancing&quot;">​</a></h3><p>For every <code>flow</code> variable $f$ declared inside the connector type: $$\\sum_{j=1}^m f(c_j) = 0$$ This yields exactly $1$ scalar conservation equation per connection set. If an inside-outside connector hierarchy boundary is crossed, the outer flow sign is inverted to preserve directional conservation: $$f_{\\text{outer}} = \\sum_{j \\in \\text{inner}} f(c_j)$$</p><h3 id="_4-stream-variable-convective-transport" tabindex="-1">4. Stream Variable Convective Transport <a class="header-anchor" href="#_4-stream-variable-convective-transport" aria-label="Permalink to &quot;4. Stream Variable Convective Transport&quot;">​</a></h3><p>For fluid ports, transport enthalpy depends on flow direction:</p><p>$$ h_{\\text{transported}} = \\begin{cases} h_{\\text{upstream}} &amp; \\text{if } \\dot{m} &gt; 0 \\ h_{\\text{downstream}} &amp; \\text{if } \\dot{m} &lt; 0 \\end{cases} $$</p><p>Direct formulation introduces a discontinuous switch that causes Newton solvers to oscillate around $\\dot{m} = 0$. ModelScript lowers stream variables using Franke&#39;s regularized <code>inStream()</code> and <code>actualStream()</code> operators: $$\\text{inStream}(c_i.h) = \\frac{\\sum_{j \\neq i, \\dot{m}_j &gt; 0} \\dot{m}<em>j \\cdot c_j.h}{\\sum</em>{j \\neq i, \\dot{m}_j &gt; 0} \\dot{m}_j}$$ Near zero flow ($|\\dot{m}_j| &lt; \\epsilon$), smooth polynomial regularization is applied to maintain $C^1$-continuity of the residual Jacobian.</p><hr><h2 id="upstream-downstream-integration" tabindex="-1">Upstream &amp; Downstream Integration <a class="header-anchor" href="#upstream-downstream-integration" aria-label="Permalink to &quot;Upstream &amp; Downstream Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Pipeline Component</th><th style="text-align:left;">Upstream Dependencies</th><th style="text-align:left;">Downstream Consumers</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>IntUnionFind</strong></td><td style="text-align:left;">AST <code>connect</code> clauses from <code>Cst</code></td><td style="text-align:left;">Connection set partition groups</td></tr><tr><td style="text-align:left;"><strong>Potential Equalizer</strong></td><td style="text-align:left;">Variable causality &amp; variability from <code>QueryEngine</code></td><td style="text-align:left;">Alias elimination (<code>eliminateArenaAliases</code>)</td></tr><tr><td style="text-align:left;"><strong>Flow Balancer</strong></td><td style="text-align:left;">Connector definitions</td><td style="text-align:left;"><code>DAEBuilder</code> linear equations</td></tr><tr><td style="text-align:left;"><strong>Stream Formulator</strong></td><td style="text-align:left;">Fluid connector declarations</td><td style="text-align:left;"><code>PantelidesEngine</code>, Nonlinear tearing loops</td></tr></tbody></table>',13))])}const b=n(s,[["render",c]]);export{f as __pageData,b as default};
